def f(a):
    return a

print(f(a=1, b=2))

class A:
    def f(self, *args):
        return len(args)

class B(A):
    def g(self):
        return super().f(1, 2, 3, 4)

print(B().g())

class C:
    def __enter__(self):
        print('enter')
        return self
    def __exit__(self, kind, value, traceback):
        print('exit')

with C():
    print('body')
